126	export type StreamEvent =
127	  | { type: "text"; text: string }
128	  | { type: "progress"; text: string }
129	  | { type: "status"; text: string }
130	  | { type: "file"; path: string; action: string }
131	  | {
132	      type: "done";
133	      credits: number;
134	      remaining: number;
135	      filesWritten: number;
136	      buildId: string | null;
137	      repairAttempts: number;
138	      repairWaived: boolean;
139	      waivedCredits: number;
140	    }
141	  | { type: "error"; message: string };
142	
143	function str(v: unknown, fallback = ""): string {
144	  return typeof v === "string" ? v : fallback;
145	}
146	function num(v: unknown, fallback = 0): number {
147	  return typeof v === "number" && Number.isFinite(v) ? v : fallback;
148	}
