150	/**
151	 * Narrow one parsed SSE payload. Returns null for anything unrecognised — a
152	 * frame we cannot read must not move the step list, and must not throw and
153	 * kill a build that is otherwise going fine. The route adds fields to `done`
154	 * over time and explicitly expects the client to ignore what it does not know.
155	 */
156	export function parseStreamEvent(raw: unknown): StreamEvent | null {
157	  if (typeof raw !== "object" || raw === null) return null;
158	  const e = raw as Record<string, unknown>;
159	  switch (e.type) {
160	    case "text":
161	      return { type: "text", text: str(e.text) };
162	    case "progress":
163	      return { type: "progress", text: str(e.text) };
164	    case "status":
165	      return { type: "status", text: str(e.text) };
166	    case "file":
167	      return { type: "file", path: str(e.path), action: str(e.action) };
168	    case "done":
169	      return {
170	        type: "done",
171	        credits: num(e.credits),
172	        remaining: num(e.remaining),
173	        filesWritten: num(e.filesWritten),
174	        buildId: typeof e.buildId === "string" ? e.buildId : null,
175	        repairAttempts: num(e.repairAttempts),
176	        repairWaived: e.repairWaived === true,
177	        waivedCredits: num(e.waivedCredits),
178	      };
179	    case "error":
180	      return { type: "error", message: str(e.message, "The build failed.") };
181	    default:
182	      return null;
183	  }
184	}
