188	export type BuildRun = {
189	  /** Fixed when the build starts. `isFirstBuild` flips the moment the user's
190	      message joins the list, so a running build must not relabel itself. */
191	  kind: "create" | "edit";
192	  index: number;
193	  outcome: BuildOutcome;
194	  /** The most recent progress/status line, VERBATIM. lib/build-narration.ts is
