197	  line: string | null;
198	  /** `file` events seen. On the sdk engine these can arrive in one batch after
199	      the build, so this is evidence a write happened — not a live count. */
200	  filesTouched: number;
201	  /** Repair passes the SERVER announced. Never inferred from a stall. */
202	  repairs: number;
203	  /**
204	   * The request was answered 200 with a readable body. That is the line
205	   * between "refused before anything happened" and "the server started work":
206	   * route.ts writes the Build row AND the user's Message row before it returns
207	   * the stream, so past this point a retry is a follow-up edit rather than a
208	   * clean re-run. Nothing else can tell those two apart.
