225	export type BuildSignal =
226	  /** POST /api/generate answered 200 and handed back a readable body. */
227	  | { kind: "accepted" }
228	  /** One frame off the stream. */
229	  | { kind: "sse"; event: StreamEvent }
230	  /** The request was refused, the fetch threw, or the stream ended without a
