234	/** Pure. The ONLY way a BuildRun changes. */
235	export function reduceBuild(run: BuildRun, signal: BuildSignal): BuildRun {
236	  if (run.outcome !== "running") return run;
237	  switch (signal.kind) {
238	    case "accepted":
239	      return { ...run, accepted: true, index: Math.max(run.index, STEP.thinking) };
240	    case "failed":
241	      return { ...run, outcome: "failed" };
242	    case "sse":
243	      return applyEvent(run, signal.event);
244	  }
245	}
