247	function applyEvent(run: BuildRun, event: StreamEvent): BuildRun {
248	  switch (event.type) {
249	    // Prose from the model. Real evidence the request is being worked on, but
250	    // it names no phase, so it moves nothing.
251	    case "text":
252	      return run;
253	
254	    case "progress":
255	    case "status": {
256	      const text = event.text;
257	      const next = { ...run, line: text || run.line };
258	
259	      // The server just told us the previous attempt did not compile. Going
260	      // back to `writing` is not a glitch — the build genuinely went back.
261	      if (REPAIR_PREFIX.test(text)) {
262	        return { ...next, index: STEP.writing, repairs: next.repairs + 1 };
263	      }
264	      if (text === COMPILING_LINE) return { ...next, index: STEP.compiling };
265	      if (WRITE_LINE.test(text)) return { ...next, index: Math.max(next.index, STEP.writing) };
266	      // "Looking through the project", "Running a command", "Picking out icons
267	      // and artwork", "Applying your changes…" — all real, none of them a
268	      // phase change. They show up in the live line and nowhere else.
269	      return { ...next, index: Math.max(next.index, STEP.thinking) };
270	    }
271	
272	    case "file":
273	      return {
274	        ...run,
275	        filesTouched: run.filesTouched + 1,
276	        index: Math.max(run.index, STEP.writing),
277	      };
278	
279	    case "done":
280	      return {
281	        ...run,
282	        outcome: "succeeded",
283	        index: LABELS[run.kind].length,
284	        line: null,
285	        // The server's own counts are authoritative over the events we
286	        // happened to see — a dropped frame must not understate the work.
287	        filesTouched: Math.max(run.filesTouched, event.filesWritten),
288	        repairs: Math.max(run.repairs, event.repairAttempts),
289	      };
290	
291	    case "error":
292	      return { ...run, outcome: "failed" };
293	  }
294	}
