296	/**
297	 * The step list, ready for `AIProgress`.
298	 *
299	 * `live` swaps the active step's generic label for the real narration line
300	 * when there is one, so "Editing the files" becomes "Writing the hero section"
301	 * — the actual tool call, not a guess about it.
302	 */
303	export function buildSteps(run: BuildRun, { live = true }: { live?: boolean } = {}): ProgressStep[] {
304	  const labels = LABELS[run.kind];
305	  if (run.outcome === "succeeded") return stepsAt(labels, labels.length);
306	  const active = Math.min(run.index, labels.length - 1);
307	  if (run.outcome === "failed") return stepsAt(labels, active, true);
308	  const shown =
309	    live && run.line
310	      ? labels.map((l, i) => (i === active ? { ...l, label: run.line as string } : l))
311	      : labels;
312	  return stepsAt(shown, active);
313	}
