318	  if (run.outcome === "succeeded") return "Change applied";
319	  if (run.outcome === "failed") return "Build failed";
320	  if (run.line) return run.line;
321	  return buildSteps(run, { live: false }).find((s) => s.state === "active")?.label ?? "Working";
